{"l":5813,"g":7,"b":1,"cefr":"B1","role":"challenge","insight":"reframing","k":"o","q":"Hvad betyder 'raise' i 'Raise your hand if you know the answer'?","o":["rejse sig","sænk","rose","ræk op / løft"],"a":"ræk op / løft","r":"'Raise' betyder at løfte noget. 'Rise' betyder at stige eller rejse sig."},
{"l":5826,"g":7,"b":1,"cefr":"B1","role":"challenge","insight":"reframing","k":"o","q":"Hvad betyder 'rise' i 'The sun rises in the east'?","o":["står op / stiger","løfter","sænker sig","går ned"],"a":"står op / stiger","r":"'Rise' betyder at stige eller stå op (om solen)."},
{"l":5839,"g":7,"b":1,"cefr":"B1","role":"challenge","insight":"reframing","k":"o","q":"Hvad betyder 'lie' i 'Don't lie to me'?","o":["ligge","lyve","lægge","le"],"a":"lyve","r":"'Lie' kan betyde at lyve eller at ligge."},
{"l":5852,"g":7,"b":1,"cefr":"B1","role":"challenge","insight":"reframing","k":"o","q":"Hvad betyder 'lay' i 'Please lay the table'?","o":["ligge","lyve","dække (bord) / lægge","lade"],"a":"dække (bord) / lægge","r":"'Lay' betyder at lægge. 'Lay the table' betyder dække bord."},
{"l":5865,"g":7,"b":1,"cefr":"B1","role":"challenge","insight":"reframing","k":"o","q":"Hvad betyder 'remind' i 'Remind me to call Grandma'?","o":["huske","gentage","glemme","minde om"],"a":"minde om","r":"'Remind' betyder at minde nogen om noget."},
{"l":5878,"g":7,"b":1,"cefr":"B1","role":"challenge","insight":"reframing","k":"o","q":"Hvad betyder 'notice' i 'Did you notice his new haircut?'","o":["lægge mærke til","notere","meddele","glemme"],"a":"lægge mærke til","r":"'Notice' betyder at lægge mærke til."},
{"l":5891,"g":7,"b":1,"cefr":"B1","role":"challenge","insight":"reframing","k":"o","q":"Hvad betyder 'ignore' i 'She ignored my message'?","o":["glemte","ignorerede / overså med vilje","besvarede","læste"],"a":"ignorerede / overså med vilje","r":"'Ignore' betyder at lade som om, man ikke ser eller hører noget."},
{"l":5904,"g":7,"b":1,"cefr":"B1","role":"challenge","insight":"reframing","k":"o","q":"Hvad betyder 'realise' i 'I didn't realise it was so late'?","o":["virkeliggøre","huske","indse / være klar over","bestemme"],"a":"indse / være klar over","r":"'Realise' betyder at blive klar over noget. Det betyder sjældent 'realisere'."},
{"l":5917,"g":7,"b":1,"cefr":"B1","role":"challenge","insight":"reframing","k":"o","q":"Hvad betyder 'pass' i 'Did you pass the exam?'","o":["aflevere","gå forbi","springe over","bestå"],"a":"bestå","r":"'Pass an exam' betyder at bestå en prøve."},
{"l":5930,"g":7,"b":1,"cefr":"B1","role":"challenge","insight":"reframing","k":"o","q":"Hvad betyder 'fail' i 'He failed his driving test'?","o":["dumpede","fejrede","faldt","fik"],"a":"dumpede","r":"'Fail' betyder at dumpe eller mislykkes."},
{"l":5942,"g":7,"b":1,"cefr":"B1","role":"challenge","insight":"reframing","k":"o","q":"Hvad betyder 'deal with' i 'I'll deal with the problem tomorrow'?","o":["handle med","tage mig af","dele","undgå"],"a":"tage mig af","r":"'Deal with' betyder at tage sig af noget."},
{"l":5955,"g":7,"b":1,"cefr":"B1","role":"challenge","insight":"reframing","k":"o","q":"Hvad betyder 'come across' i 'I came across an old photo'?","o":["kom over","gik forbi","faldt over / fandt tilfældigt","tog et billede af"],"a":"faldt over / fandt tilfældigt","r":"'Come across' betyder at finde noget tilfældigt."},
{"l":5968,"g":7,"b":1,"cefr":"B1","role":"challenge","insight":"reframing","k":"o","q":"Hvad betyder 'fill in' i 'Fill in the form, please'?","o":["fylde op","indsende","læse igennem","udfylde"],"a":"udfylde","r":"'Fill in a form' betyder at udfylde en formular."},
{"l":5981,"g":7,"b":1,"cefr":"B1","role":"challenge","insight":"reframing","k":"o","q":"Hvad betyder 'show off' i 'Stop showing off!'?","o":["prale / blære sig","vise frem til en udstilling","slukke","tage af"],"a":"prale / blære sig","r":"'Show off' betyder at blære sig."},
{"l":5994,"g":7,"b":1,"cefr":"B1","role":"challenge","insight":"reframing","k":"o","q":"Hvad betyder 'turn up' i 'Only five people turned up'?","o":["skruede op","dukkede op","vendte om","takkede nej"],"a":"dukkede op","r":"'Turn up' kan betyde at dukke op eller at skrue op."},
{"l":6007,"g":7,"b":2,"cefr":"B1","role":"challenge","insight":"reframing","k":"o","q":"Hvad betyder 'go off' i 'The alarm went off at six'?","o":["slukkede","gik væk","ringede / gik i gang","blev dårlig"],"a":"ringede / gik i gang","r":"'Go off' betyder her, at alarmen gik i gang."},
{"l":6020,"g":7,"b":2,"cefr":"B1","role":"challenge","insight":"reframing","k":"o","q":"Hvad betyder 'go off' i 'This milk has gone off'?","o":["er løbet ud","er gået i gang","er blevet kold","er blevet sur / dårlig"],"a":"er blevet sur / dårlig","r":"Om mad betyder 'go off', at den er blevet dårlig."},
{"l":6033,"g":7,"b":2,"cefr":"B1","role":"challenge","insight":"reframing","k":"o","q":"Hvad betyder 'hand in' i 'Hand in your homework on Monday'?","o":["aflevere","række op","holde i hånden","give tilbage til eleven"],"a":"aflevere","r":"'Hand in' betyder at aflevere."},
{"l":6046,"g":7,"b":2,"cefr":"B1","role":"challenge","insight":"reframing","k":"o","q":"Hvad betyder 'try on' i 'Can I try on these shoes?'","o":["forsøge at","prøve (tøj/sko)","prøve kræfter med","købe"],"a":"prøve (tøj/sko)","r":"'Try on' bruges om at prøve tøj eller sko."},
{"l":6059,"g":7,"b":2,"cefr":"B1","role":"challenge","insight":"reframing","k":"o","q":"Hvad betyder 'check in' i 'We checked in at the hotel at three'?","o":["tjekkede ud","bestilte","tjekkede ind","betalte"],"a":"tjekkede ind","r":"'Check in' er at melde sin ankomst på et hotel eller i en lufthavn."},
{"l":6071,"g":7,"b":2,"cefr":"B1","role":"challenge","insight":"reframing","k":"o","q":"Hvilket ord passer: 'I need to ___ an appointment with the doctor.'","o":["do","take","give","make"],"a":"make","r":"Man siger 'make an appointment'."},
{"l":6084,"g":7,"b":2,"cefr":"B1","role":"challenge","insight":"reframing","k":"o","q":"Hvilket ord passer: 'Let's ___ a break. We've been working for hours.'","o":["take","make","do","have to"],"a":"take","r":"Man siger 'take a break' (eller 'have a break')."},
{"l":6097,"g":7,"b":2,"cefr":"B1","role":"challenge","insight":"reframing","k":"o","q":"Hvilket ord passer: 'He ___ a promise to his mother.'","o":["did","made","took","gave up"],"a":"made","r":"Man siger 'make a promise'."},
{"l":6110,"g":7,"b":2,"cefr":"B1","role":"challenge","insight":"reframing","k":"o","q":"Hvilket ord passer: 'Can you ___ the washing-up tonight?'","o":["make","take","do","have"],"a":"do","r":"Man siger 'do the washing-up' (vaske op)."}
]$$::jsonb) AS e
JOIN (VALUES
  ('o', 'ordforråd', 'recall', 'factual', 'surface_association'),
  ('h', 'hverdagsudtryk', 'comprehension', 'conceptual', 'surface_association'),
  ('g', 'grammatik', 'application', 'applied', 'overgeneralization'),
  ('l', 'læseforståelse', 'analysis', 'inferential', 'surface_association')
) AS m(k, concept, skill, dtype, mis) ON m.k = e->>'k';
